Section GENA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (m0 : amem) (DT WK T nbb maxW minB scl cons minW mwr e1 len1 : Z) (sorted : list (option Z)) (js jt : list byte)
    (ncells : nat) (rs0 rv : list Z).
  Variable Q : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis PLC : x2placeA RNG m0 SPA DT WK js ncells.
  Hypothesis HT : 1 <= T <= 12.
  Hypothesis HNBB : 2 <= nbb <= 13.
  Hypothesis HWE : 2 <= maxW + 1 <= nbb.
  Hypothesis HCONS : 1 <= cons <= 11.
  Hypothesis HMW : minW = Z.max 1 mwr /\ mwr = cons + nbb - T /\ minW < maxW + 1.
  Hypothesis HLEN : len1 = 2 ^ (T - cons) /\ 1 <= T - cons <= 11.
  Hypothesis HE1 : e1 <= 256.
  Hypothesis LRS : length rs0 = 15%nat.
  Hypothesis HRSV : forall w, 1 <= w <= maxW -> 0 <= Znth w rs0 <= Znth (w + 1) rs0 /\ Znth (w + 1) rs0 <= 256.
  Hypothesis LRV : length rv = 156%nat.
  Variable PRV : Z -> Prop.
  Hypothesis HPRV : forall w, minW <= w <= maxW -> PRV (rv_idx cons w).
  Hypothesis HRVR : forall w, minW <= w <= maxW -> 0 <= Znth (rv_idx cons w) rv < 2^31.
  Hypothesis RSA0 : u32arr asegs m0 (WK + 676) (map (Z_to_bv 64) rs0).
  Hypothesis RVA0 : rv_atA m0 WK rv PRV.
  Notation INV m1 dt := (x2fA_inv m0 m1 SPA DT WK T nbb maxW minB scl js jt sorted ncells dt).
