  Notation GENW := [(DT + 4, DT + 4 + 4 * Z.of_nat ncells); (SPA + 264, SPA + 280); (SPA + 296, SPA + 568);
                    (SPA + 616, SPA + 704)].
  Notation SKA := (WK + 52 * cons + 4 * minW).
  Notation D1 := (cons * 65536 + 16777216).
