    rw_cells asegs m (SPA + 88) [C8 (Z_to_bv 64 SKA)] /\ rw_cells asegs m (SPA + 152) [C8 (Z_to_bv 64 minW)]
    /\ rw_cells asegs m (SPA + 168) [C8 (Z_to_bv 64 (Z.shiftr SKA 3)); C8 (Z_to_bv 64 D1); C8 (Z_to_bv 64 mwr)]
