    /\ rw_cells asegs m (SPA + 296) [CB 272 j296] /\ L2X m
    /\ rw_cells asegs m (SPA + 616) [CB 8 jw] /\ rw_cells asegs m (SPA + 624) [CB 80 jsp].

  Lemma genA_loop : forall f s dt start m1 mC r w264 w272 j296 jw jsp
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x17 x18 x19 x20 x21 x22 x23 x26 x27 x28 x29 x30 x31 : word),
    fill_two_level f dt s e1 start len1 T cons minW (maxW + 1) rv sorted rs0 nbb = Ok r ->
    Z.of_nat f = e1 - s + 1 -> 0 <= s < e1 -> 0 <= start -> start + len1 * (e1 - s) <= 4096 ->
    INV m1 dt -> genfrA m1 w264 w272 j296 jw jsp -> munch GENW mC m1 -> wmono asegs mC m1 ->
    (forall m2 dt' w264' w272' j296' jw' jsp'
            (y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23 y25 y26 y27 y28 y29 y30 y31 : word),
       r = dt' -> INV m2 dt' -> genfrA m2 w264' w272' j296' jw' jsp' -> munch GENW mC m2 -> wmono asegs mC m2 ->
       evtF asegs RNG Q (x2nextA SP SPA gp tp F fc m2 y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23
                           y25 y26 y27 y28 y29 y30 y31)) ->
    evtF asegs RNG Q
      (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) x10 x11 x12 x13 x14 x15 (Z_to_bv 64 s) x17
               x18 x19 x20 x21 x22 x23 (Z_to_bv 64 2147450880) (Z_to_bv 64 start) x26 x27 x28 x29 x30 x31)
          F (Z_to_bv 64 0x82310) fc None m1 (seg_rom asegs)).
